# This gives us our period-4 pattern
left_4_cols = []
for r in range(4):
    left_4_cols.append([grid[r][c] for c in range(4)])

print("Left 4x4 pattern:")
for row in left_4_cols:
    print(row)

# Build output: for each cell (r,c), get value from left_4_cols[r%4][c%4]
# Cross (r=4 or c=4) stays as 4
output = []
for r in range(11):
    row = []
    for c in range(11):
        if c == 4 or r == 4:
            row.append(4)  # cross
        else:
            row.append(left_4_cols[r % 4][c % 4])
    output.append(row)

output_grid = output
print("\nOutput grid:")
for row in output_grid:
    print(row)

